#!/bin/bash
# Continue the interrupted 259253 eval. E5-large already wrote the new
# revision except RoSTS (Hub 404, restored before this job). Clustering
# RORetrieval is still unpinned and will fail-and-continue.
#
# Do not edit this file or run_all_models.sh while the job is running:
# bash re-reads the script by byte offset and can execute a fragment
# (`o: command not found` → exit 127).

set -euo pipefail

SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
ROOT=$(cd "${SCRIPT_DIR}/.." && pwd)
cd "${ROOT}"

RUNNER="${ROOT}/apptainer-exec-romteb.sh"
OUTPUT_DIR=${1:-"${ROOT}/results"}

echo "=== Continue eval: RoSTS for E5-large ==="
"${RUNNER}" "${ROOT}/romteb/run_benchmark.py" \
  --model intfloat/multilingual-e5-large \
  --loader auto \
  --tasks RoSTS \
  --output "${OUTPUT_DIR}" \
  || echo "[WARN] E5 RoSTS failed; continuing roster."

echo "=== Continue eval: remaining roster in run_all_models.sh ==="
bash "${ROOT}/scripts/run_all_models.sh" "${OUTPUT_DIR}"
